select client_id, app_id, client_code, client_name, description, create_time, update_time
from ai_client_def
where client_id = #{clientId}

select version_id, client_id, version, status, model_name, prompt_template, output_schema, create_time, update_time
from ai_client_version
where client_id = #{clientId}
  and version = #{version}
